-- Symptomate — Перевірка симптомів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'symptomate.com' OR LOWER(`name`) = LOWER('Symptomate'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Symptomate', NULL, 'https://symptomate.com', NULL, NULL, 'Безкоштовна перевірка симптомів від Infermedica: адаптивні запитання, ймовірні стани та рекомендація, до якого лікаря і як терміново звернутися; 13+ мов.', 'A free symptom checker by Infermedica: adaptive questions, possible conditions and a recommendation on which doctor to see and how urgently; 13+ languages.', 'Symptomate створили лікарі компанії Infermedica, щоб допомогти людям зрозуміти можливі причини симптомів і наступні кроки. Ви вказуєте симптоми (без обмеження кількості), відповідаєте на адаптивні запитання, а сервіс показує перелік імовірних станів і рекомендований рівень допомоги — від самодогляду до невідкладної. Є окремі режими для жінок, чоловіків, батьків і літніх людей, карти тіла та оцінка для дітей. Доступно понад 13 мовами. У ЄС Symptomate має статус медичного виробу класу IIb; проведено понад 27 млн опитувань. Для користувачів безкоштовний. Важливо: Symptomate не ставить діагноз і не замінює лікаря.', 'Symptomate was created by doctors at Infermedica to help people understand possible causes of their symptoms and the next steps. You enter symptoms (with no limit), answer adaptive questions, and it shows a list of probable conditions and a recommended level of care — from self-care to emergency. There are dedicated modes for women, men, parents and seniors, body maps and paediatric assessments. It is available in 13+ languages. In the EU Symptomate is a Class IIb medical device; more than 27 million interviews have been completed. It is free for users. Important: Symptomate does not provide a diagnosis and does not replace a doctor.', 'Адаптивні запитання про симптоми
Імовірні стани й рекомендований рівень допомоги
Режими для дітей, жінок, чоловіків і літніх
13+ мов, медичний виріб класу IIb у ЄС', 'Adaptive symptom questions
Probable conditions and recommended care level
Modes for children, women, men and seniors
13+ languages, Class IIb medical device in the EU', 'Люди, які хочуть зрозуміти свої симптоми й підготуватися до візиту до лікаря.', 'People who want to make sense of their symptoms and prepare for a doctor''s visit.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
