INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Symptomate was created by doctors at Infermedica to help people understand possible causes of their symptoms and the next steps. You enter symptoms (with no limit), answer adaptive questions, and it shows a list of probable conditions and a recommended level of care — from self-care to emergency. There are dedicated modes for women, men, parents and seniors, body maps and paediatric assessments. It is available in 13+ languages. In the EU Symptomate is a Class IIb medical device; more than 27 million interviews have been completed. It is free for users. Important: Symptomate does not provide a diagnosis and does not replace a doctor.', 'manual' FROM DUAL WHERE @new = 1;
