-- K Health — Перевірка симптомів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'khealth.com' OR LOWER(`name`) = LOWER('K Health'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'K Health', NULL, 'https://khealth.com', NULL, NULL, 'Первинна медична допомога з AI у США: AI-асистент PatientGPT збирає симптоми, а сертифіковані лікарі консультують онлайн 24/7 у партнерстві з провідними клініками.', 'AI-enabled primary care in the US: the PatientGPT assistant collects symptoms, and board-certified doctors consult online 24/7 in partnership with leading health systems.', 'K Health поєднує AI і лікарів для первинної медичної допомоги. AI-асистент PatientGPT проводить первинне опитування про симптоми й готує інформацію для лікаря, а сертифіковані лікарі приймають онлайн цілодобово — при гострих станах, хронічних хворобах і для профілактики; додаються також ендокринологія й дерматологія. Платформа інтегрується з електронними медкартами й працює в партнерстві з великими системами охорони здоров''я США, зокрема Mass General Brigham, Mayo Clinic, Cedars-Sinai та Penn Medicine. Сервіс доступний у США; вартість залежить від партнерської клініки й страхування.', 'K Health combines AI and doctors for primary care. The PatientGPT AI assistant runs the initial symptom intake and prepares information for the clinician, and board-certified doctors see patients online 24/7 — for acute conditions, chronic care and prevention; endocrinology and dermatology are being added. The platform integrates with electronic health records and partners with major US health systems, including Mass General Brigham, Mayo Clinic, Cedars-Sinai and Penn Medicine. The service is available in the US; cost depends on the partner health system and insurance.', 'AI-опитування про симптоми (PatientGPT)
Онлайн-лікарі 24/7
Гострі, хронічні стани та профілактика
Інтеграція з медкартами клінік-партнерів', 'AI symptom intake (PatientGPT)
Online doctors 24/7
Acute, chronic and preventive care
EHR integration with partner health systems', 'Пацієнти в США, чиї клініки чи страховики співпрацюють з K Health.', 'Patients in the US whose health systems or insurers partner with K Health.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
