-- SkinVision — Догляд за шкірою
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'skinvision.com' OR LOWER(`name`) = LOWER('SkinVision'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SkinVision', NULL, 'https://www.skinvision.com', NULL, NULL, 'Застосунок для оцінки ризику раку шкіри: AI аналізує фото родимки чи плями, за потреби фото переглядають дерматологи; сертифікований медичний виріб з маркуванням CE.', 'A skin cancer risk check app: AI analyses a photo of a mole or spot, with dermatologist review when needed; a certified CE-marked medical device.', 'SkinVision допомагає вчасно помітити тривожні зміни на шкірі. Ви фотографуєте родимку чи пляму камерою телефона, AI оцінює ризик, а за потреби знімок переглядає команда кваліфікованих дерматологів. Застосунок веде карту тіла, щоб відстежувати плями з часом, враховує тип шкіри та фактори ризику й підказує, чи варто і коли звернутися до лікаря. SkinVision — сертифікований медичний виріб з маркуванням CE; ним користуються понад 3 млн людей, переважно в Нідерландах, Бельгії та Великій Британії. Ціни в євро: разова перевірка — €6,99, 3 місяці — €24,99, 12 місяців — €49,99. Застосунок не замінює огляд у дерматолога.', 'SkinVision helps you spot worrying skin changes early. You photograph a mole or spot with your phone camera, AI assesses the risk, and a team of qualified dermatologists reviews the image when needed. The app keeps a body map to track spots over time, takes your skin type and risk factors into account and advises whether and when to see a doctor. SkinVision is a certified CE-marked medical device used by more than 3 million people, mainly in the Netherlands, Belgium and the UK. Prices in euros: a single check — €6.99, 3 months — €24.99, 12 months — €49.99. The app does not replace an examination by a dermatologist.', 'AI-оцінка ризику за фото родимки
Перевірка дерматологами за потреби
Карта тіла й відстеження змін
Медичний виріб з маркуванням CE', 'AI risk assessment from a mole photo
Dermatologist review when needed
Body map and change tracking
CE-marked medical device', 'Люди з великою кількістю родимок або підвищеним ризиком раку шкіри.', 'People with many moles or an increased risk of skin cancer.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
