-- Flo — Жіноче здоров'я
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'flo.health' OR LOWER(`name`) = LOWER('Flo'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Flo', NULL, 'https://flo.health', NULL, NULL, 'Трекер менструального циклу, овуляції, вагітності та перименопаузи, яким користуються понад 420 млн людей; режим анонімності та доступ для партнера.', 'A tracker for periods, ovulation, pregnancy and perimenopause used by more than 420 million people; Anonymous Mode and partner sharing.', 'Flo — один із найпопулярніших застосунків для жіночого здоров''я. Він відстежує менструальний цикл і симптоми, прогнозує місячні та фертильні дні, допомагає тим, хто планує вагітність, супроводжує вагітність тиждень за тижнем і підтримує в період перименопаузи. Застосунок дає персональні прогнози й поради та містить матеріали, перевірені медичними експертами. Для приватності є режим анонімності, а функція Flo for Partners дає змогу ділитися інформацією з партнером. Flo користуються понад 420 млн людей. Працює на iOS і Android; основні функції доступні безкоштовно, розширені — за платною підпискою, ціну показано в застосунку. Flo не є методом контрацепції й не замінює лікаря.', 'Flo is one of the most popular women''s health apps. It tracks your cycle and symptoms, predicts periods and fertile days, helps people trying to conceive, follows pregnancy week by week and supports you through perimenopause. The app gives personal predictions and tips and includes content reviewed by medical experts. For privacy there is Anonymous Mode, and Flo for Partners lets you share information with your partner. More than 420 million people use Flo. It works on iOS and Android; core features are free and advanced ones require a paid subscription, priced in the app. Flo is not a contraceptive method and does not replace a doctor.', 'Прогноз місячних і фертильних днів
Режими планування й вагітності
Підтримка в перименопаузі
Режим анонімності та Flo for Partners', 'Period and fertile-day predictions
Trying-to-conceive and pregnancy modes
Perimenopause support
Anonymous Mode and Flo for Partners', 'Жінки, які стежать за циклом, планують вагітність, вагітні або в перименопаузі.', 'Women who track their cycle, are trying to conceive, are pregnant or in perimenopause.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
