-- Clue — Жіноче здоров'я
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'helloclue.com' OR LOWER(`name`) = LOWER('Clue'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Clue', NULL, 'https://helloclue.com', NULL, NULL, 'Трекер циклу з європейським підходом до приватності (GDPR): прогнози місячних і фертильності, режими вагітності й перименопаузи, інтеграція з носимими пристроями.', 'A cycle tracker with a European approach to privacy (GDPR): period and fertility predictions, pregnancy and perimenopause modes and wearable integration.', 'Clue допомагає розуміти свій менструальний цикл і репродуктивне здоров''я. Застосунок відстежує місячні та симптоми, аналізує цикли й прогнозує фертильне вікно; режим Clue Conceive допомагає планувати вагітність, є режим вагітності та інструменти для перименопаузи. Можна створювати власні мітки, бачити дані в наочних графіках, налаштовувати нагадування, ділитися циклом через Clue Connect та підключати носимі пристрої. Компанія працює за європейськими правилами захисту даних (GDPR). Доступний на iOS і Android; базова версія безкоштовна, розширені функції — у підписці Clue Plus (ціну вказано при оформленні).', 'Clue helps you understand your menstrual cycle and reproductive health. The app tracks periods and symptoms, analyses cycles and predicts your fertile window; Clue Conceive helps you plan a pregnancy, and there is a pregnancy mode and perimenopause tools. You can create custom tags, see your data in clear charts, set reminders, share your cycle through Clue Connect and connect wearables. The company follows European data protection rules (GDPR). It is available on iOS and Android; the basic version is free, and advanced features come with a Clue Plus subscription (priced at checkout).', 'Аналіз циклу й прогноз фертильності
Clue Conceive, режими вагітності й перименопаузи
Власні мітки й нагадування
GDPR та інтеграція з носимими пристроями', 'Cycle analysis and fertility predictions
Clue Conceive, pregnancy and perimenopause modes
Custom tags and reminders
GDPR and wearable integration', 'Жінки, для яких важлива приватність даних про здоров''я.', 'Women for whom the privacy of health data matters.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
