-- Natural Cycles — Жіноче здоров'я
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'naturalcycles.com' OR LOWER(`name`) = LOWER('Natural Cycles'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Natural Cycles', NULL, 'https://www.naturalcycles.com', NULL, NULL, 'Єдиний застосунок для контрацепції без гормонів, схвалений FDA: алгоритм визначає фертильні дні за температурою тіла й показує, коли потрібен захист.', 'The only FDA-cleared birth control app, hormone-free: its algorithm identifies fertile days from body temperature and shows when you need protection.', 'Natural Cycles (NC°) — застосунок, що допомагає запобігати вагітності без гормонів або планувати її. Алгоритм аналізує температуру тіла та інші дані циклу й щодня показує, чи є день фертильним і чи потрібен захист. Natural Cycles — єдиний застосунок для контрацепції, схвалений FDA (уже понад 8 років); його ефективність становить 98% при правильному використанні та 93% при типовому, що відповідає категорії ефективності таблеток. Застосунок також допомагає тим, хто планує вагітність. Ціну підписки вказано при оформленні й вона залежить від країни. Метод не захищає від інфекцій, що передаються статевим шляхом; перед вибором контрацепції варто порадитися з лікарем.', 'Natural Cycles (NC°) is an app that helps you prevent pregnancy without hormones or plan one. Its algorithm analyses body temperature and other cycle data and shows each day whether it is fertile and whether you need protection. Natural Cycles is the only FDA-cleared birth control app (for more than 8 years); it is 98% effective with perfect use and 93% with typical use, the same effectiveness category as the pill. The app also helps those trying to conceive. The subscription price is shown at checkout and depends on your country. The method does not protect against sexually transmitted infections; talk to a doctor before choosing contraception.', 'Контрацепція без гормонів, схвалена FDA
Визначення фертильних днів за температурою
Ефективність 93% при типовому використанні
Режим планування вагітності', 'FDA-cleared hormone-free birth control
Fertile-day detection from temperature
93% typical-use effectiveness
Pregnancy planning mode', 'Жінки, які шукають контрацепцію без гормонів або планують вагітність.', 'Women looking for hormone-free contraception or planning a pregnancy.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
